<section><a class="back-link" href="/merchant/orders">← All orders</a><div class="page-heading order-heading"><div><p class="eyebrow">Placed <?= e(gmdate('M j, Y H:i',strtotime($order['placed_at']))) ?> UTC</p><h1><?= e($order['reference']) ?></h1><p class="muted">WhatsApp: <?= $order['whatsapp_opened_at']?'open attempted at '.e(gmdate('M j, H:i',strtotime($order['whatsapp_opened_at']))).' UTC':'not opened yet' ?>. This does not confirm the message was sent.</p></div><span class="badge order-<?= e(strtolower($order['status'])) ?>"><?= e(ucfirst(strtolower($order['status']))) ?></span></div>
<div class="order-detail-grid"><div class="order-main"><section class="panel order-items-panel"><div class="panel-title"><h2>Items</h2><span><?= count($order['items']) ?> line<?= count($order['items'])===1?'':'s' ?></span></div><?php foreach($order['items']as$item):?><article class="order-line"><div><strong><?= e($item['quantity']) ?> × <?= e($item['product_name']) ?></strong><?php if($item['variant_label']):?><span><?= e($item['variant_label']) ?></span><?php endif ?><?php if($item['sku_snapshot']):?><small>SKU <?= e($item['sku_snapshot']) ?></small><?php endif ?></div><div><span><?= e($order['currency_code']) ?> <?= e($item['unit_price']) ?> each</span><strong><?= e($order['currency_code']) ?> <?= e($item['line_total']) ?></strong></div></article><?php endforeach ?><?php if((float)$order['discount_amount']>0||(float)($order['offer_discount_amount']??0)>0||$order['free_delivery']):?><div class="order-total muted-row"><span>Subtotal</span><strong><?= e($order['currency_code']) ?> <?= e($order['subtotal']) ?></strong></div><?php if((float)($order['offer_discount_amount']??0)>0):?><div class="order-total muted-row"><span>Offer<?= $order['offer_snapshot']?' ('.e($order['offer_snapshot']).')':'' ?></span><strong>−<?= e($order['currency_code']) ?> <?= e($order['offer_discount_amount']) ?></strong></div><?php endif ?><?php if((float)$order['discount_amount']>0):?><div class="order-total muted-row"><span>Discount<?= $order['discount_code_snapshot']?' ('.e($order['discount_code_snapshot']).')':'' ?></span><strong>−<?= e($order['currency_code']) ?> <?= e($order['discount_amount']) ?></strong></div><?php endif ?><?php if($order['free_delivery']):?><div class="order-total muted-row"><span>Delivery</span><strong>Free delivery code applied</strong></div><?php endif ?><?php endif ?><div class="order-total"><span>Total</span><strong><?= e($order['currency_code']) ?> <?= e($order['total']) ?></strong></div></section>
<section class="panel"><h2>Status history</h2><ol class="status-history"><?php foreach($order['history']as$event):?><li><span></span><div><strong><?= e(ucfirst(strtolower($event['status']))) ?></strong><small><?= e(gmdate('M j, Y H:i',strtotime($event['created_at']))) ?> UTC<?= $event['actor_name']?' · '.e($event['actor_name']):' · Customer checkout' ?></small><?php if($event['reason_code']):?><small>Reason: <?= e($cancelReasons[$event['reason_code']]??$event['reason_code']) ?><?= $event['reason_note']?' — '.e($event['reason_note']):'' ?></small><?php endif ?></div></li><?php endforeach ?></ol></section></div>
<aside class="order-side"><section class="panel"><h2>Customer</h2><dl class="order-facts"><div><dt>Name</dt><dd><?= e($order['customer_name']) ?></dd></div><div><dt>Phone</dt><dd><a href="tel:<?= e($order['customer_phone']) ?>"><?= e($order['customer_phone']) ?></a></dd></div><div><dt>Delivery</dt><dd><?= nl2br(e($order['delivery_address'])) ?></dd></div><?php if($order['notes']):?><div><dt>Notes</dt><dd><?= nl2br(e($order['notes'])) ?></dd></div><?php endif ?></dl></section>
<?php if($nextStatuses):?><section class="panel status-actions"><h2>Update status</h2><p>Choose the next real fulfillment state. Completed and cancelled orders are final.</p><?php foreach($nextStatuses as$next):?><?php if($next==='CANCELLED'):?><form method="post" action="/merchant/orders/<?= e($order['reference']) ?>/status" class="cancel-order-form" data-confirm="Cancel this order?" data-confirm-message="This will mark the order cancelled and restore tracked variant stock. This cannot be reversed."><?= csrf_field() ?><input type="hidden" name="status" value="CANCELLED"><label>Cancellation reason<select name="reason_code" required><option value="">Choose a reason…</option><?php foreach($cancelReasons as$code=>$label):?><option value="<?= e($code) ?>"><?= e($label) ?></option><?php endforeach ?></select></label><label>Note <span class="optional">Optional</span><textarea name="reason_note" rows="2" maxlength="300" placeholder="Any extra detail for your own records"></textarea></label><button class="button danger-ghost" type="submit">Cancel order</button></form><?php else:?><form method="post" action="/merchant/orders/<?= e($order['reference']) ?>/status"><?= csrf_field() ?><input type="hidden" name="status" value="<?= e($next) ?>"><button class="button primary" type="submit">Mark <?= e(ucfirst(strtolower($next))) ?></button></form><?php endif ?><?php endforeach ?></section><?php endif ?></aside></div></section>
